const VIDEO_TYPES=new Set(['video/mp4','video/webm']);
// Мелкие фото (например, сохранённые из веб-версии Telegram-канала, 600×800) на площадках выглядят мутно — принимаем только от 1080 пикселей по ширине.
const MIN_PHOTO_WIDTH=1080;
async function photoSize(w,file){if(typeof w.createImageBitmap!=='function')return null;try{const bitmap=await w.createImageBitmap(file);const size={width:bitmap.width,height:bitmap.height};if(typeof bitmap.close==='function')bitmap.close();return size;}catch{return null;}}
async function smallPhotoIssue(w,files){for(const file of files){if(!IMAGE_TYPES.has(file.type))continue;const size=await photoSize(w,file);if(size&&size.width<MIN_PHOTO_WIDTH)return'Фото «'+file.name+'» слишком маленькое: '+size.width+'×'+size.height+' пикселей. Нужно не меньше '+MIN_PHOTO_WIDTH+' по ширине, иначе на площадках оно будет мутным. Загрузите оригинал из галереи телефона, а не картинку, сохранённую из Telegram-канала или с сайта.';}return'';}
